import {completedPhotoDay} from './photo-completion.mjs';
import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const digest=x=>createHash('sha256').update(x).digest('hex'),hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x);
const fail=(message,status)=>Object.assign(Error(message),{status});
const short=(s,max=2000)=>typeof s==='string'&&s.length<=max?s:null;
async function names(dir){try{return await fs.readdir(dir);}catch(e){if(e.code==='ENOENT')return [];throw e;}}
async function json(file,max=65536){const s=await fs.lstat(file);if(!s.isFile()||s.isSymbolicLink()||s.size>max)throw Error('Invalid private evidence');return JSON.parse(await fs.readFile(file,'utf8'));}
export function createPhotoProposalService({root,objectsRoot,snapshotFor,inventoryFor,readImage,now=Date.now}){
 let cachedQueue=null,cachedStamp='',inventory=null,inventoryAt=0;
 async function queue(pinned){if(pinned){const q=pinned.queue,byKey=new Map(),ids=new Set();for(const item of q.items){const day=item.scopeDate||item.recordKey.slice(0,10);if(item.duplicateOf||q.scope&&(day<q.scope.from||day>q.scope.to))continue;if(!(q.completedReportDays||[]).includes(day))ids.add(item.id);for(const key of new Set([item.recordKey,item.datedRecordKey].filter(Boolean))){const list=byKey.get(key)||[];list.push(item);byKey.set(key,list);}}return {...q,total:ids.size,ids,byKey};}let st;try{st=await fs.stat(path.join(root,'queue.private.json'));}catch(e){if(e.code==='ENOENT')return {items:[],rubricVersion:null,total:0,byKey:new Map(),ids:new Set()};throw e;}
  const stamp=st.mtimeMs+':'+st.size;if(cachedQueue&&stamp===cachedStamp)return cachedQueue;
  const q=await json(path.join(root,'queue.private.json'),64*1024*1024);if(!Array.isArray(q.items)||q.items.length>200000||q.total!==q.items.length||typeof q.rubricVersion!=='string')throw Error('Invalid proposal queue');
  const scope=q.scope??null;if(scope&&(!/^\d{4}-\d{2}-\d{2}$/.test(scope.from||'')||!/^\d{4}-\d{2}-\d{2}$/.test(scope.to||'')||scope.from>scope.to))throw Error('Invalid proposal scope');
  const completedReportDays=q.completedReportDays??[];if(!Array.isArray(completedReportDays)||completedReportDays.some(d=>typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d)))throw Error('Invalid completed report days');
  const byKey=new Map(),ids=new Set(),allIds=new Set();for(const item of q.items){if(!hex(item.id)||allIds.has(item.id)||typeof item.recordKey!=='string'||!hex(item.urlSha256)||item.datedRecordKey!=null&&typeof item.datedRecordKey!=='string')throw Error('Invalid proposal queue');allIds.add(item.id);const day=item.scopeDate||item.recordKey.slice(0,10);if(item.duplicateOf||scope&&(day<scope.from||day>scope.to))continue;if(!completedReportDays.includes(day))ids.add(item.id);for(const key of new Set([item.recordKey,item.datedRecordKey].filter(Boolean))){const list=byKey.get(key)||[];list.push(item);byKey.set(key,list);}}
  cachedStamp=stamp;inventory=null;return cachedQueue={...q,total:ids.size,scope,completedReportDays,byKey,ids};
 }
 async function sourceOnlyAvailable(row){const id=row?.photo_sha256;if(!hex(id))return false;try{let b;if(readImage)b=await readImage(id);else{const file=path.join(objectsRoot,id),st=await fs.lstat(file);if(!st.isFile()||st.isSymbolicLink()||st.size>8*1024*1024)return false;b=await fs.readFile(file);}return Buffer.isBuffer(b)&&b.length<=8*1024*1024&&digest(b)===id&&(b[0]===255&&b[1]===216&&b[2]===255||b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))||b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WEBP');}catch{return false;}}
 async function counts(q){const time=now();if(inventory&&time-inventoryAt<10000)return inventory;const [p,u,workers,flags]=await Promise.all(['proposals','unavailable','workers','flags'].map(d=>names(path.join(root,d))));const flagged=new Set(flags.filter(f=>/^[a-f0-9]{64}\.json$/.test(f)&&q.ids.has(f.slice(0,64))).map(f=>f.slice(0,64))),done=new Set(p.filter(f=>/^[a-f0-9]{64}\.json$/.test(f)&&q.ids.has(f.slice(0,64))&&!flagged.has(f.slice(0,64))).map(f=>f.slice(0,64))),unavailable=new Set(u.filter(f=>/^[a-f0-9]{64}\.json$/.test(f)&&q.ids.has(f.slice(0,64))&&!done.has(f.slice(0,64))&&!flagged.has(f.slice(0,64))).map(f=>f.slice(0,64)));
  let activeWorkers=0,updatedAt=null;for(const f of workers.slice(0,1000)){if(!/^[a-zA-Z0-9_-]+\.json$/.test(f))continue;try{const w=await json(path.join(root,'workers',f)),t=Date.parse(w.updatedAt);if(w.status==='reviewing'&&Number.isFinite(t)&&t<=time&&time-t<=300000)activeWorkers++;if(Number.isFinite(t)&&(!updatedAt||t>Date.parse(updatedAt)))updatedAt=w.updatedAt;}catch{}}
  inventoryAt=time;return inventory={total:q.total,proposed:done.size,unavailable:unavailable.size,needsReview:flagged.size,pending:q.total-done.size-unavailable.size-flagged.size,activeWorkers,updatedAt,scope:q.scope??null,completedReportDays:q.completedReportDays??[]};
 }
 return async params=>{
  const hashes=params.getAll('snapshot'),keys=params.getAll('record');if([...params.keys()].some(k=>!['snapshot','record'].includes(k))||hashes.length!==1||!hex(hashes[0])||keys.length<1||keys.length>25||new Set(keys).size!==keys.length||keys.some(k=>!k||k.length>300))throw fail('Invalid proposal request',400);
  let snapshot;
  try{snapshot=await snapshotFor(hashes[0]);}
  catch(error){
   if(error?.code==='ENOENT'||error?.status===404)throw fail('Unknown report',409);
   throw error;
  }
  if(!Array.isArray(snapshot?.rows))throw fail('Unknown report',409);const rows=new Map(snapshot.rows.map(r=>[r.key,r]));if(keys.some(k=>!rows.has(k)))throw fail('Unknown record',409);
  const pinned=inventoryFor?await inventoryFor(hashes[0]):null;
  const evidence=async(kind,id)=>{if(!pinned)return json(path.join(root,kind,id+'.json'));if(!pinned[kind]?.[id])throw Object.assign(Error('Missing pinned receipt'),{code:'ENOENT'});return pinned[kind][id];};
  const q=await queue(pinned),progress=pinned?{total:q.total,proposed:Object.keys(pinned.proposals).filter(id=>q.ids.has(id)&&!pinned.flags[id]).length,needsReview:Object.keys(pinned.flags).filter(id=>q.ids.has(id)).length,unavailable:Object.keys(pinned.unavailable).filter(id=>q.ids.has(id)).length,pending:q.total-[...q.ids].filter(id=>pinned.proposals[id]||pinned.flags[id]||pinned.unavailable[id]).length,activeWorkers:0}:await counts(q);
  const proposals=await Promise.all(keys.map(async recordKey=>{
   if(completedPhotoDay(rows.get(recordKey),q.completedReportDays))return {recordKey,status:'retained'};
   const row=rows.get(recordKey).delivery||{},candidates=q.byKey.get(recordKey)||[];if(!candidates.length)return {recordKey,status:rows.get(recordKey).sourceOnly?.assessmentState==='unavailable'&&await sourceOnlyAvailable(row)?'pending':'unavailable'};
   const recovery=pinned?.attempts;
   const urlSha256=typeof row.photo_url==='string'&&row.photo_url?digest(row.photo_url):null,proofTimestamp=String(row.raw_upload||row.upload||null),matching=candidates.filter(i=>i.urlSha256===urlSha256&&String(i.proofTimestamp??null)===proofTimestamp&&(!row.photo_sha256||!i.imageSha256||row.photo_sha256===i.imageSha256));if(!matching.length)return {recordKey,status:'stale'};
   for(const candidate of matching){try{const flag=await evidence('flags',candidate.id);if(flag.id!==candidate.id||flag.status!=='needs_review'||!short(flag.reason)||!short(flag.flaggedAt,100))return {recordKey,status:'stale'};return {recordKey,status:'needs_review',reason:flag.reason,flaggedAt:flag.flaggedAt,...(typeof flag.uncertainty==='string'?{uncertainty:flag.uncertainty}:{})};}catch(e){if(e.code!=='ENOENT')return {recordKey,status:'stale'};}}
   if(rows.get(recordKey).sourceOnly?.assessmentState==='unavailable'&&!hex(row.photo_sha256)){if(matching.some(i=>recovery?.[i.id]))return {recordKey,status:matching.some(i=>recovery?.[i.id]?.status==='submitted')?'submitted':'needs_recovery'};return {recordKey,status:'unavailable'};}
   let p,item,unavailable=false;for(const candidate of matching){try{p=await evidence('proposals',candidate.id);item=candidate;break;}catch(e){if(e.code!=='ENOENT')return {recordKey,status:'stale'};try{await evidence('unavailable',candidate.id);unavailable=true;}catch{}}}if(!item){if(matching.some(i=>recovery?.[i.id])){const submitted=matching.some(i=>recovery?.[i.id]?.status==='submitted');return {recordKey,status:submitted?'submitted':'needs_recovery',reason:submitted?'Review submitted; awaiting a validated result. An interrupted submission requires inspection before any retry.':'A submitted or blocked review needs inspection before any retry.'};}if(rows.get(recordKey).sourceOnly?.assessmentState==='unavailable'&&!unavailable&&!await sourceOnlyAvailable(row))return {recordKey,status:'unavailable'};return {recordKey,status:unavailable?'unavailable':'pending'};}
   if(p.id!==item.id||p.recordKey!==item.recordKey||p.urlSha256!==urlSha256||String(p.proofTimestamp??null)!==proofTimestamp||p.status!=='proposed'||!hex(p.imageSha256)||p.rubricVersion!==q.rubricVersion||p.reviewerModel!=='gpt-6.1-terra'||!Number.isInteger(p.grade)||p.grade<0||p.grade>3||!short(p.reason)||short(p.uncertainty)===null||!short(p.reviewedAt,100)||item.cachedSha256!=null&&item.cachedSha256!==p.imageSha256||row.photo_sha256&&row.photo_sha256!==p.imageSha256)return {recordKey,status:'stale'};
   try{let bytes;if(readImage)bytes=await readImage(p.imageSha256);else{const file=path.join(objectsRoot,p.imageSha256),st=await fs.lstat(file);if(!st.isFile()||st.isSymbolicLink()||st.size>8*1024*1024)return {recordKey,status:'stale'};bytes=await fs.readFile(file);}if(!Buffer.isBuffer(bytes)||bytes.length>8*1024*1024||digest(bytes)!==p.imageSha256)return {recordKey,status:'stale'};}catch{return {recordKey,status:'stale'};}
   return {recordKey,status:'proposed',imageSha256:p.imageSha256,grade:p.grade,reason:p.reason,uncertainty:p.uncertainty,rubricVersion:p.rubricVersion,reviewerModel:p.reviewerModel,reviewedAt:p.reviewedAt};
  }));return {proposals,progress,rubricVersion:q.rubricVersion};
 };
}
